// src/components/PolicyCard.js
import React from "react";

const PolicyCard = () => {
  return (
    <div className="policy-card">
      <h2>Información de la Póliza</h2>
      <div className="policy-details">
        <p><strong>Número de Póliza:</strong> 123456789</p>
        <p><strong>Nombre del Asegurado:</strong> Juan Pérez</p>
        <p><strong>Vigencia:</strong> 01/01/2023 - 31/12/2023</p>
        <p><strong>Tipo de Seguro:</strong> Automóvil</p>
        <p><strong>Estado:</strong> Activa</p>
      </div>
    </div>
  );
};

export default PolicyCard;
